class PaymentGateway {
    public void processPayment(double amount) {
        System.out.println("Processing generic payment of $" + amount);
    }
}

class CreditCardGateway extends PaymentGateway {
    public void processPayment(double amount) {
        System.out.println("Charging $" + amount + " to Credit Card via VISA network");
    }
}

class PayPalGateway extends PaymentGateway {
    public void processPayment(double amount) {
        System.out.println("Authorizing PayPal payment of $" + amount + " via secure token");
    }
}

public class PolymorphismIntroDemo {
    public static void main(String[] args) {
        // Polymorphic reference: Parent type holding child instances
        PaymentGateway p1 = new CreditCardGateway();
        PaymentGateway p2 = new PayPalGateway();

        // The exact same method call produces different behaviors at runtime!
        p1.processPayment(150.00);
        p2.processPayment(89.50);
    }
}

