class Notification {
    public void send(String recipient, String message) {
        System.out.println("Sending notification to " + recipient + ": " + message);
    }
}

class EmailNotification extends Notification {
    public void send(String recipient, String message) {
        System.out.println("Sending Email to " + recipient + ": " + message);
    }
}

class PushNotification extends Notification {
    public void send(String recipient, String message) {
        System.out.println("Sending Push Notification to " + recipient + ": " + message);
    }
}

public class Main {
    public static void main(String[] args) {
        Notification n1 = new EmailNotification();
        Notification n2 = new PushNotification();
        n1.send("user@domain.com", "Welcome aboard!");
        n2.send("DEVICE-TOKEN-998", "New message received");
    }
}

class TaxCalculator {
    public double computeTax(double amount) {
        return amount * 0.10;
    }
    public double computeTax(double amount, double rate) {
        return amount * (rate / 100.0);
    }
}

class CorporateTaxCalculator extends TaxCalculator {
    public double computeTax(double amount) {
        return amount * 0.25;
    }
}

public class Main {
    public static void main(String[] args) {
        TaxCalculator standard = new TaxCalculator();
        System.out.println("Individual Standard Tax: $" + standard.computeTax(1000.0));
        System.out.println("Individual Custom Tax: $" + standard.computeTax(1000.0, 15.0));

        TaxCalculator corporate = new CorporateTaxCalculator();
        System.out.println("Corporate Overridden Tax: $" + corporate.computeTax(1000.0));
    }
}

